<?php
declare(strict_types=1);
namespace Flexgrid\Modules\AdminBanking\Infrastructure\Persistence;
use Flexgrid\Modules\AdminBanking\Contract\BankImportRepositoryInterface;use Flexgrid\Modules\AdminBanking\Domain\Model\BankImport;use Flexgrid\Modules\AdminBanking\Exception\DuplicateBankImportException;use Flexgrid\Modules\AdminCore\ValueObject\TenantId;
final class PdoBankImportRepository implements BankImportRepositoryInterface{private$connection;public function __construct(\PDO$connection){$this->connection=$connection;}public function insert(BankImport$import):void{$this->assertTransaction();$statement=$this->connection->prepare('INSERT INTO `admin_bank_import` (`tenant_id`,`public_id`,`bank_account_public_id`,`format`,`file_name`,`checksum_sha256`,`row_count`,`imported_count`,`skipped_count`,`imported_at`) VALUES (:tenant,:public,:account,:format,:file,:checksum,:rows,:imported,:skipped,:at)');try{$statement->execute([':tenant'=>$import->getTenantId()->toString(),':public'=>$import->getPublicId(),':account'=>$import->getBankAccountPublicId(),':format'=>$import->getFormat(),':file'=>$import->getFileName()===''?null:$import->getFileName(),':checksum'=>$import->getChecksum(),':rows'=>$import->getRowCount(),':imported'=>$import->getImportedCount(),':skipped'=>$import->getSkippedCount(),':at'=>$import->getImportedAt()]);}catch(\PDOException$exception){if((string)$exception->getCode()==='23000'){throw new DuplicateBankImportException('Bankbestand is al geïmporteerd.',0,$exception);}throw$exception;}}public function findByChecksum(TenantId$tenant,string$account,string$format,string$checksum):?BankImport{$statement=$this->connection->prepare('SELECT * FROM `admin_bank_import` WHERE `tenant_id`=:tenant AND `bank_account_public_id`=:account AND `format`=:format AND `checksum_sha256`=:checksum LIMIT 1');$statement->execute([':tenant'=>$tenant->toString(),':account'=>trim($account),':format'=>strtolower(trim($format)),':checksum'=>strtolower(trim($checksum))]);$row=$statement->fetch(\PDO::FETCH_ASSOC);return is_array($row)?new BankImport((string)$row['public_id'],new TenantId((string)$row['tenant_id']),(string)$row['bank_account_public_id'],(string)$row['format'],(string)($row['file_name']??''),(string)$row['checksum_sha256'],(int)$row['row_count'],(int)$row['imported_count'],(int)$row['skipped_count'],(int)$row['imported_at']):null;}private function assertTransaction():void{if(!$this->connection->inTransaction()){throw new \LogicException('Bankimportopslag vereist een actieve transactie.');}}}
